def IsometryFirstJetRigidity : Prop :=
  ∀ (z : ℂ) (a b : LocalDiscIsometry z), a z = b z →
    deriv a z = deriv b z → a.toFun =ᶠ[𝓝 z] b.toFun

def LocalDiscIsometryExtension : Prop :=
  ∀ (z : ℂ) (φ : LocalDiscIsometry z), ∃ A : GlobalDiscIsometry,
    φ.toFun =ᶠ[𝓝 z] A.toFun

def SurfaceAnalyticRegularity : Prop :=
  ∀ (F : (ℂ × ℂ) → ℂ) (p : ℂ × ℂ),
    (∀ᶠ q in 𝓝 p, DifferentiableAt ℂ F q) → AnalyticAt ℂ F p

def HomDegreeLaw (theory : LineBundleDegreeTheory) : Prop :=
  ∀ (D : Curve) (N T : HolomorphicLineCocycle D) (H : HomLineCocycle N T),
    theory.degree D H.bundle = theory.degree D T - theory.degree D N

def ProductCoverExistence : Prop :=
  ∀ (X : CompactComplexSurface) (C D : Curve)
    (q : FiniteUnramifiedCover X (C.productSurface D)), Nonempty (ProductCoverModel q)

def UniformizingDiscCharts : Prop :=
  ∀ (B : Curve) (g : ConformalMetric B), B.Hyperbolic → HasConeData g 0 →
    HasConstantCurvature g 0 (-1) → ∀ b : B, Nonempty (UniformizingDiscChart g b)

def SmoothProperFibreModels : Prop :=
  ∀ (X : CompactComplexSurface) (f : Fibration X),
    IsProperMap f.map → f.Smooth → ∀ b : f.base, Nonempty (FibreCurveModel f b)

def NonsingularJointLocusOpen : Prop :=
  ∀ (X : CompactComplexSurface) (B C : Curve)
    (f : HolomorphicMap X B) (h : HolomorphicMap X C),
    IsOpen {x : X | Function.Bijective (jointDifferential f h x)}

def CompactUnramifiedCurveCovering : Prop :=
  ∀ (C B : Curve) (a : HolomorphicMap C B),
    (∀ p : C, Function.Bijective (mfderiv 𝓘(ℂ, ℂ) 𝓘(ℂ, ℂ) a p)) → IsCoveringMap a

def AnalyticDividedDifferences : Prop :=
  ∀ (f : ℂ → ℂ) (a : ℂ), AnalyticAt ℂ f a →
    AnalyticAt ℂ (fun z : ℂ × ℂ => dslope f z.1 (z.1 + z.2)) (a, 0)

def LineBundleDegreeGaugeInvariance (theory : LineBundleDegreeTheory) : Prop :=
  ∀ (C : Curve) (L K : HolomorphicLineCocycle C), HolomorphicLineGauge L K →
    theory.degree C L = theory.degree C K

def KodairaBaseHyperbolicity : Prop :=
  ∀ (X : CompactComplexSurface) (f : Fibration X),
    f.Smooth → f.NonIsotrivial → f.Hyperbolic

def DoubleKodairaExistence : Prop :=
  ∃ (X : CompactComplexSurface) (f g : KodairaFibration X),
    ¬ Fibration.Equivalent f.val g.val
